var n=[{title:`Elige un rango de repeticiones`,text:`Elige un ejercicio, un número de series y un rango, por ejemplo tres series de 8–12 repeticiones. Empieza con un peso que te permita llegar al extremo inferior del rango con una técnica estable y unas pocas repeticiones en reserva. El rango no tiene por qué ser 8–12. Tu objetivo y el ejercicio fijan los límites.`},{title:`Gánate el aumento de carga`,text:`Primero, haz más repeticiones buenas con el mismo peso a lo largo de varias sesiones. Cuando todas las series alcancen el extremo superior del rango con el esfuerzo que planeaste, añade el incremento de peso más pequeño que tengas. Tus repeticiones normalmente bajarán de nuevo hacia el extremo inferior, y el ciclo vuelve a empezar.`},{title:`Ejemplo`,text:`Semana 1: remos con mancuerna de 12 kg con 10, 9, 8. Semana 2: 11, 10, 9. Semana 3: 12, 12, 12 con un control estable. Semana 4: prueba con 14 kg para 9, 8, 8, si puedes asumir ese salto con buena técnica. Estos números muestran cómo puede ir. No tienes que mejorar cada semana.`},{title:`Cuándo adaptar la regla`,text:`Un gran salto de peso puede ser demasiado difícil, sobre todo para músculos pequeños o con equipamiento doméstico limitado. En ese caso, quédate con tu carga actual, añade repeticiones totales o elige una variante intermedia. Si una sesión resulta inusualmente agotadora, repite el último objetivo y deja la progresión para más adelante. El progreso real suele subir y bajar.`},{title:`Cómo usar TrainUp`,text:`Tu plan da a cada ejercicio series y un objetivo de repeticiones, y durante un entrenamiento registras las repeticiones que completas en cada serie. TrainUp no prescribe pesos, así que tú decides cuándo añadir carga. Cuando llegues al extremo superior del rango en todas las series, comprueba tu RPE y tu técnica antes de subir de peso.`}];var o=[{label:`Declaración de posición del ACSM de 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NSCA: seguridad y fundamentos del entrenamiento de fuerza`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Mayo Clinic: técnica del entrenamiento con pesas (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var s={sections:n,sources:o};export{s as default,n as sections,o as sources};